package com.aoo.bcg.common.cache;
import com.aoo.bcg.gamespi.time.AuthoritativeTimeSource;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ReadThroughCacheMigrationTest{static class Memory implements CacheAccessor{Map<String,String>values=new HashMap<>();List<String>writes=new ArrayList<>();public Optional<String>get(String key){return Optional.ofNullable(values.get(key));}public void set(String key,String value,Duration ttl){values.put(key,value);writes.add(key);}}@Test void readsLegacyOnlyBeforeCutoffCopiesOnceAndNeverDualWrites(){Instant now=Instant.parse("2026-08-23T00:00:00Z");Memory cache=new Memory();cache.values.put("legacy-room-1","value");CacheKey target=CacheKey.of("prod","game","room",1,2);var migration=new ReadThroughCacheMigration(cache,new AuthoritativeTimeSource(Clock.fixed(now,ZoneOffset.UTC)),now.plusSeconds(60));assertEquals("value",migration.read(target,"legacy-room-1",Duration.ofSeconds(20)).orElseThrow());migration.write(target,"next",Duration.ofSeconds(30));assertEquals(List.of(target.value(),target.value()),cache.writes);assertFalse(cache.writes.contains("legacy-room-1"));var stopped=new ReadThroughCacheMigration(cache,new AuthoritativeTimeSource(Clock.fixed(now.plusSeconds(61),ZoneOffset.UTC)),now.plusSeconds(60));assertFalse(stopped.legacyReadsEnabled());}}
